def validate_production_secret_key(secret_key):
    value = str(secret_key or "")
    normalized = value.strip().lower()

    if value != value.strip():
        raise ImproperlyConfigured("SECRET_KEY must not contain leading or trailing whitespace.")
    if len(value) < MINIMUM_PRODUCTION_SECRET_LENGTH:
        raise ImproperlyConfigured(
            f"SECRET_KEY must contain at least {MINIMUM_PRODUCTION_SECRET_LENGTH} characters."
        )
    if len(set(value)) < MINIMUM_PRODUCTION_SECRET_UNIQUE_CHARACTERS:
        raise ImproperlyConfigured("SECRET_KEY does not contain enough character diversity.")
    if normalized.isdigit() or any(marker in normalized for marker in WEAK_SECRET_MARKERS):
        raise ImproperlyConfigured("SECRET_KEY contains a known weak or placeholder value.")

    return value

def validate_production_broker(broker_url, *, task_always_eager):
    """Reject an implicit in-request task runner in production."""
    value = str(broker_url or "")
    if task_always_eager:
        raise ImproperlyConfigured(
            "CELERY_TASK_ALWAYS_EAGER must be False in production; background work "
            "may not run inside the request."
        )
    if not value or value.startswith("memory://"):
        raise ImproperlyConfigured(
            "A real Celery broker is required in production; set REDIS_URL or "
            "CELERY_BROKER_URL."
        )
    return value

function Gate() {
  const [fontsLoaded] = useAppFonts();
  const themeReady = useTheme().ready;
  const langReady = useLang().ready;
  const hydrate = useAuth((s) => s.hydrate);

  useEffect(() => {
    hydrate();
  }, [hydrate]);

  if (!fontsLoaded || !themeReady || !langReady) return <LoadingState />;
  return <Navigator />;
}

export default function App() {
  return (
    <SafeAreaProvider>
      <ThemeProvider>
        <LanguageProvider>
          <QueryClientProvider client={queryClient}>
            <StatusBar style="auto" />
            <Gate />
          </QueryClientProvider>
        </LanguageProvider>
      </ThemeProvider>
    </SafeAreaProvider>
  );
}

class ProductionSecretKeyTests(SimpleTestCase):
    def test_rejects_short_or_placeholder_secrets(self):
        weak_values = [
            "",
            "x",
            "12345678",
            "short-secret",
            "docker-local-secret-change-before-production",
        ]

        for value in weak_values:
            with self.subTest(value=value):
                with self.assertRaises(ImproperlyConfigured):
                    validate_production_secret_key(value)

    def test_accepts_long_diverse_secret(self):
        secret = "Prod-2026!Saffron_River+Atlas#Quartz$Nimbus%Orbit&Harbor"

        self.assertEqual(validate_production_secret_key(secret), secret)

def test_accepts_long_diverse_secret(self):
    secret = "Prod-2026!Saffron_River+Atlas#Quartz$Nimbus%Orbit&Harbor"

    self.assertEqual(validate_production_secret_key(secret), secret)

class CorsPreflightTests(SimpleTestCase):
    endpoints = (
        "/api/v1/auth/login/",
        "/api/v1/auth/onboarding/",
    )

    def test_idempotent_mutations_allow_browser_preflight(self):
        # Test exactly the origins the deployment allows, so this can't drift
        # from CORS_ALLOWED_ORIGINS again.
        origins = list(settings.CORS_ALLOWED_ORIGINS)
        if not origins:
            self.skipTest("CORS_ALLOWED_ORIGINS is empty in this environment.")

        client = Client()

        for endpoint in self.endpoints:
            for origin in origins:
                with self.subTest(endpoint=endpoint, origin=origin):
                    response = client.options(
                        endpoint,
                        HTTP_ORIGIN=origin,
                        HTTP_ACCESS_CONTROL_REQUEST_METHOD="POST",
                        HTTP_ACCESS_CONTROL_REQUEST_HEADERS=(
                            "authorization,content-type,idempotency-key"
                        ),
                    )

                    self.assertEqual(response.status_code, 200)
                    self.assertEqual(
                        response["Access-Control-Allow-Origin"],
                        origin,
                    )
                    allowed_headers = {
                        header.strip().lower()
                        for header in response[
                            "Access-Control-Allow-Headers"
                        ].split(",")
                    }
                    self.assertIn("authorization", allowed_headers)
                    self.assertIn("content-type", allowed_headers)
                    self.assertIn("idempotency-key", allowed_headers)

