def _message_from_data(data):
    if isinstance(data, dict) and "detail" in data:
        return str(data["detail"])
    if isinstance(data, list) and data:
        return str(data[0])
    if data:
        return "Validation error."
    return "An unexpected error occurred."

def platform_exception_handler(exc, context):
    response = exception_handler(exc, context)

    if isinstance(exc, PlatformAPIError):
        return Response(
            {
                "code": _normalize_code(exc.code),
                "message": exc.message,
                "details": exc.details,
            },
            status=exc.status_code,
        )

    if response is None:
        if isinstance(exc, Http404):
            return Response(
                {
                    "code": "NOT_FOUND",
                    "message": "The requested resource was not found.",
                    "details": {},
                },
                status=status.HTTP_404_NOT_FOUND,
            )
        return None

    code = getattr(exc, "default_code", None)
    if not code and isinstance(response.data, dict):
        detail = response.data.get("detail")
        code = getattr(detail, "code", None)

    response.data = {
        "code": _normalize_code(code or response.status_code),
        "message": _message_from_data(response.data),
        "details": response.data,
    }
    return response

def _timed(probe):
    started_at = time.monotonic()
    try:
        probe()
    except Exception as exc:
        return "unavailable", round((time.monotonic() - started_at) * 1000, 2), exc
    return "ok", round((time.monotonic() - started_at) * 1000, 2), None

def check_database():
    def probe():
        connection.ensure_connection()
        with connection.cursor() as cursor:
            cursor.execute("SELECT 1")
            cursor.fetchone()

    status, latency, exc = _timed(probe)
    if isinstance(exc, OperationalError) or exc is not None:
        return "unavailable", latency
    return status, latency

