            "title_en": f"Questions on {top_mistake.topic_en}",
            "sub_fa": f"پرتکرارترین اشتباه تو — {top_mistake.count} بار",
            "sub_en": f"Your top recurring mistake — {top_mistake.count}x",
            "minutes": minutes,
            "mistake_id": top_mistake.id,
