  constructor(status: number, body: ApiErrorBody) {
    super(body.message ?? body.detail ?? "Request failed.");
    this.name = "ApiError";
    this.status = status;
    this.code = body.code ?? "API_ERROR";
    this.details = body.details ?? body;
  }
}

