}: {
  onPress: () => void;
  children: React.ReactNode;
  size?: number;
}) {
  const { colors, shadows } = useTheme();
  return (
    <Pressable
      onPress={onPress}
      style={[
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: colors.softBg,
          alignItems: "center",
