def prepare_identity_data(apps, schema_editor):
    User = apps.get_model("auth", "User")
    Token = apps.get_model("authtoken", "Token")
    ContentType = apps.get_model("contenttypes", "ContentType")
    Permission = apps.get_model("auth", "Permission")
    Role = apps.get_model("accounts", "Role")
    RoleAssignment = apps.get_model("accounts", "RoleAssignment")

    normalized_emails = {}
    for user in User.objects.order_by("id").iterator():
        email = (user.email or "").strip().lower()
        if email:
            duplicate_user_id = normalized_emails.get(email)
            if duplicate_user_id is not None:
                raise RuntimeError(
                    "Case-insensitive duplicate user emails must be resolved "
                    f"before applying accounts.0003: user {duplicate_user_id} "
                    f"and user {user.id} both use {email}."
                )
            normalized_emails[email] = user.id
        if user.email != email:
            user.email = email
            user.save(update_fields=["email"])

    Token.objects.all().delete()

    content_type, _ = ContentType.objects.get_or_create(
        app_label="accounts",
        model="securityauditevent",
    )
    permission_objects = {}
    for codename, name in PERMISSIONS.items():
        permission, _ = Permission.objects.update_or_create(
            content_type=content_type,
            codename=codename,
            defaults={"name": name},
        )
        permission_objects[codename] = permission

    roles = {}
    for key, codenames in ROLE_PERMISSIONS.items():
        role, _ = Role.objects.update_or_create(
            key=key,
            defaults={
                "name": key.replace("_", " ").title(),
                "description": f"System role: {key}.",
                "is_system": True,
            },
        )
        role.permissions.set(
            [permission_objects[codename] for codename in codenames]
        )
        roles[key] = role

    for user in User.objects.order_by("id").iterator():
        RoleAssignment.objects.get_or_create(
            user=user,
            role=roles["learner"],
            revoked_at__isnull=True,
        )
        if user.is_superuser:
            RoleAssignment.objects.get_or_create(
                user=user,
                role=roles["platform_admin"],
                revoked_at__isnull=True,
            )

