export function shadow(mode: ThemeMode) {
  const heavy = mode === "dark";
  return {
    raised: {
      shadowColor: "#000",
      shadowOpacity: heavy ? 0.5 : 0.1,
      shadowRadius: heavy ? 30 : 18,
      shadowOffset: { width: 0, height: heavy ? 12 : 6 },
      elevation: heavy ? 12 : 4,
